INSERT INTO "public"."exercises" ("id", "created_at", "uid", "name", "description") VALUES ('2', '2025-08-05 00:13:33.856549+00', '3', 'Burpees', '4x10: Jump to Push-up ladder'), ('3', '2025-08-05 00:23:23.624678+00', '3', 'Jog', '3 kilometers'), ('5', '2025-08-05 13:32:28.445975+00', '2', 'Barbell Bicep Curls', 'Hold bar in and, and curl keeping elbows stationary putting tension on the bicep.'), ('6', '2025-08-05 14:01:11.633573+00', '2', 'Bench Press', 'Lie down on bench and press weight perpendicular to your body in an upwards motion.'), ('7', '2025-08-07 18:35:43.427738+00', '2', 'Incline Bench Press', 'Same as bench press, but the bench is set to an incline to focus on the upper pectoral muscle'), ('8', '2025-08-08 02:09:02.632151+00', '2', 'Tricep Push Down', 'Use bar or cables to push downwards and put pressure on triceps.');